$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({x + h})} - f{(x)}}{h} = \lim\limits_{h\rightarrow 0}\frac{{({x + h})}^{4} - x^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{x^{4} + 4x^{3}h + 6x^{2}h^{2} + 4xh^{3} + h^{4} - x^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{4x^{3}h + 6x^{2}h^{2} + 4xh^{3} + h^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{({4x^{3} + 6x^{2}h + 4xh^{2} + h^{3}})} = 4x^{3}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({x + h})} - f{(x)}}{h} = \lim\limits_{h\rightarrow 0}\frac{b^{ x + h} - b^{ x}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{b^{ x}b^{ h} - b^{ x}}{h} = \lim\limits_{h\rightarrow 0}\frac{b^{ x}{({b^{ h} - 1})}}{h}}}
  \end{array}$$

$$\begin{matrix}
  {g(x) = kx^{3} + lx^{2} + mx + n} & {0 \leqslant x < 10} \\
  {h(x) = px^{3} + qx^{2} + rx + s} & {90 < x \leqslant 100}
  \end{matrix}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\frac{d}{\mathit{dx}}\left( {xe^{ x}} \right)}} \\
  {\phantom{f^{\prime}(x)} = {x\frac{d}{\mathit{dx}}\left( e^{ x} \right) + e^{ x}\frac{d}{\mathit{dx}}(x)}} \\
  {\phantom{f^{\prime}(x)} = {xe^{ x} + e^{ x} \cdot 1 = \left( {x + 1} \right)e^{ x}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{''}(x)} = {\frac{d}{\mathit{dx}}\left\lbrack {\left( {x + 1} \right)e^{ x}} \right\rbrack}} \\
  {\phantom{f^{''}(x)} = {\left( {x + 1} \right)\frac{d}{\mathit{dx}}\left( e^{ x} \right) + e^{ x}\frac{d}{\mathit{dx}}\left( {x + 1} \right)}} \\
  {\phantom{f^{''}(x)} = {\left( {x + 1} \right)e^{ x} + e^{ x} \cdot 1 = \left( {x + 2} \right)e^{ x}}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{dy}{\mathit{dx}} = \frac{\left( {1 + x^{2}} \right)\frac{d}{\mathit{dx}}\left( e^{ x} \right) - e^{ x}\frac{d}{\mathit{dx}}\left( {1 + x^{2}} \right)}{\left( {1 + x^{2}} \right)^{2}}} \\
  {\phantom{\frac{dy}{\mathit{dx}}} = {\frac{\left( {1 + x^{2}} \right)e^{ x} - e^{ x}\left( {2x} \right)}{\left( {1 + x^{2}} \right)^{2}} = \frac{e^{ x}\left( {1 - 2x + x^{2}} \right)}{\left( {1 + x^{2}} \right)^{2}}}} \\
  {\phantom{\frac{dy}{\mathit{dx}}} = \frac{e^{ x}\left( {1 - x} \right)^{2}}{\left( {1 + x^{2}} \right)^{2}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\sin x \cdot \lim\limits_{h\rightarrow 0}\frac{\cos h - 1}{h} + \lim\limits_{h\rightarrow 0}\cos x \cdot \lim\limits_{h\rightarrow 0}\frac{\sin h}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\left( {\sin x} \right) \cdot 0 + \left( {\cos x} \right) \cdot 1 = \cos x}}
  \end{array}$$

$$\begin{array}{lc}
  {{f^{\prime}(x)} = \frac{\left( {1 + \tan x} \right)\frac{d}{\mathit{dx}}\left( {\sec x} \right) - \sec x\frac{d}{\mathit{dx}}\left( {1 + \tan x} \right)}{\left( {1 + \tan x} \right)^{2}}} & \\
  {\phantom{f^{\prime}(x)} = \frac{\left( {1 + \tan x} \right)\sec x\tan x - \sec x \cdot \sec^{2}x}{\left( {1 + \tan x} \right)^{2}}} & \\
  {\phantom{f^{\prime}(x)} = \frac{\sec x\left( {\tan x + \tan^{2}x - \sec^{2}x} \right)}{\left( {1 + \tan x} \right)^{2}}} & \\
  {\phantom{f^{\prime}(x)} = \frac{\sec x\left( {\tan x - 1} \right)}{\left( {1 + \tan x} \right)^{2}}} & {\qquad\left( \sec^{2}x = \tan^{2}x + 1 \right)}
  \end{array}$$

$$\begin{array}{lll}
  \upsilon & = & {\frac{ds}{dt} = \frac{d}{dt}\left( {4\cos t} \right) = 4\frac{d}{dt}\left( {\cos t} \right) = - 4\sin t} \\
  a & = & {\frac{\mathit{dv}}{dt} = \frac{d}{dt}\left( {- 4\sin t} \right) = - 4\frac{d}{dt}\left( {\sin t} \right) = - 4\cos t}
  \end{array}$$

$$\frac{\mathit{dy}}{\mathit{dx}} = \frac{d}{\mathit{dx}}{\underset{\begin{matrix}
  {inner} \\
  {function}
  \end{matrix}}{\underset{︸}{({\sin x})}}}^{2} = \underset{\begin{matrix}
  {derivative} \\
  {of\ outer} \\
  {function}
  \end{matrix}}{\underset{︸}{2\quad \cdot}}\underset{\begin{matrix}
  {evaluated} \\
  {at\ inner} \\
  {function}
  \end{matrix}}{\underset{︸}{({\sin x})}} \cdot \underset{\begin{matrix}
  {derivative} \\
  {of\ inner} \\
  {function}
  \end{matrix}}{\underset{︸}{\cos x}}$$

$$\begin{array}{l}
  {{f^{\prime}(x)} = {\cos(\cos({\tan x}))\frac{d}{\mathit{dx}}\cos(\tan x)}} \\
  {\phantom{f^{\prime}(x)} = {\cos(\cos(\tan x)){\lbrack - \sin(\tan x)\rbrack}\frac{d}{\mathit{dx}}(\tan x)}} \\
  {\phantom{f^{\prime}(x)} = {- \cos(\cos({\tan x}))\sin(\tan x)\sec^{2}x}}
  \end{array}$$

$$\begin{array}{l}
  {{\frac{d}{\mathit{dx}}{(b^{x})}} = {\frac{d}{\mathit{dx}}{(e^{{({\ln b})}x})} = e^{{({\ln b})}x}\frac{d}{\mathit{dx}}{\lbrack({\ln b})}x}\rbrack} \\
  {\phantom{\frac{d}{\mathit{dx}}{(b^{ x})}} = {e^{{({\ln b})}x}(\ln b) = b^{ x}\ln b}}
  \end{array}$$

$$\begin{array}{rll}
  {\ln y} & = & {\ln x^{\sqrt{x}} = \sqrt{x}\ln x} \\
  \frac{y^{\prime}}{y} & = & {\sqrt{x} \cdot \frac{1}{x} + \left( {\ln x} \right)\frac{1}{2\sqrt{x}}} \\
  y^{\prime} & = & {y\left( {\frac{1}{\sqrt{x}} + \frac{\ln x}{2\sqrt{x}}} \right) = x^{\sqrt{x}}\left( \frac{2 + \ln x}{2\sqrt{x}} \right)}
  \end{array}$$

$$\begin{array}{l}
  {{\cosh^{2}x - \sinh^{2}x} = {\left( \frac{e^{ x} + e^{- x}}{2} \right)^{2} - \left( \frac{e^{ x} - e^{- x}}{2} \right)^{2}}} \\
  {\phantom{\cosh^{2}x - \sinh^{2}x} = {\frac{e^{2x} + 2 + e^{- 2x}}{4} - \frac{e^{2x} - 2 + e^{- 2x}}{4}}} \\
  {\phantom{\cosh^{2}x - \sinh^{2}x} = {\frac{4}{4} = 1}}
  \end{array}$$

$$\begin{array}{l}
  {{\frac{d}{\mathit{dx}}{\lbrack{\tanh^{- 1}{({\sin x})}}\rbrack}} = {\frac{1}{1 - {({\sin x})}^{2}}\frac{d}{\mathit{dx}}{({\sin x})}}} \\
  {\phantom{\frac{d}{\mathit{dx}}{\lbrack{\tanh^{- 1}{({\sin x})}}\rbrack}} = {\frac{1}{1 - \sin^{2}x}\cos x = \frac{\cos x}{\cos^{2}x} = \sec x}}
  \end{array}$$
